SELECT product_id AS productId, SUM(quantity) AS stockQuantity FROM t_stock_balance WHERE product_id IN
#{pid}
AND deleted_flag = 0 GROUP BY product_id

SELECT ps.product_id AS productId, ps.supplier_id AS supplierId, s.supplier_name AS supplierName, ps.supply_price AS supplyPrice, ps.default_flag AS defaultFlag FROM t_product_supplier ps LEFT JOIN t_supplier s ON s.supplier_id = ps.supplier_id WHERE ps.product_id IN
#{pid}
AND ps.deleted_flag = 0
